// Extrae "Chapter name" de cada fila (algunas filas traen el valor en
// "chapter_name" en vez de "Chapter name", así que revisamos ambas)
const items = $input.all();
const chapterSet = new Set();

for (const item of items) {
  const raw = item.json['Chapter name'] || item.json['chapter_name'] || '';
  const name = raw.toString().trim();
  if (name) chapterSet.add(name);
}

const uniqueChapters = Array.from(chapterSet);

// HubSpot Search API soporta el operador "IN" con varios valores,
// pero conviene batchear para no pasarte del límite de la request.
// Empieza con 50 y ajusta si HubSpot te devuelve error de tamaño.
const BATCH_SIZE = 50;
const batches = [];
for (let i = 0; i < uniqueChapters.length; i += BATCH_SIZE) {
  batches.push(uniqueChapters.slice(i, i + BATCH_SIZE));
}

return batches.map((batch) => ({
  json: {
    filterGroups: [
      {
        filters: [
          {
            propertyName: 'name', // <-- confirma que "Chapter name" matchea con el property "name" del company
            operator: 'IN',
            values: batch,
          },
        ],
      },
    ],
    properties: [
      'name',
      'slt_destination__date_and_season_hs',
      'slt_destination_date_and_season_2',
    ],
    limit: 100,
  },
}));

// 1) Diccionario: nombre de company en HubSpot (normalizado) -> { expected_slt_1, expected_slt_2 }
const hubspotBatches = $input.all(); // salida del HTTP Request (uno por batch)
const companyMap = new Map();

for (const batchItem of hubspotBatches) {
  const results = batchItem.json.results || [];
  for (const company of results) {
    const props = company.properties || {};
    const key = (props.name || '').toString().trim().toLowerCase();
    if (!key) continue;

    const values = {
      expected_slt_1: props.slt_destination__date_and_season_hs || '',
      expected_slt_2: props.slt_destination_date_and_season_2 || '',
    };

    if (!companyMap.has(key)) {
      companyMap.set(key, values);
    } else {
      // Si hay dos companies con el mismo "name" (puede pasar: viste "total": 51
      // para un batch de 50 nombres), nos quedamos con la que sí tenga datos.
      const existing = companyMap.get(key);
      const existingHasData = existing.expected_slt_1 || existing.expected_slt_2;
      const newHasData = values.expected_slt_1 || values.expected_slt_2;
      if (!existingHasData && newHasData) companyMap.set(key, values);
    }
  }
}

// 2) Recorrer las 710 filas originales y anexar los dos campos
// const rows = $('Get Join SLT 2026-2027 rows').all();
const rows = $('Split Out').all();

return rows.map((row) => {
  const raw = row.json['Chapter name'] || row.json['chapter_name'] || '';
  const chapterKey = raw.toString().trim().toLowerCase();
  const match = companyMap.get(chapterKey);

  return {
    json: {
      ...row.json,
      expected_slt_1: match ? match.expected_slt_1 : (row.json.expected_slt_1 || ''),
      expected_slt_2: match ? match.expected_slt_2 : (row.json.expected_slt_2 || ''),
    },
  };
});

